INSERT INTO "OPEX IN" ("Cost Center", "Account", "Versions", "Years", "Months", v, ver, is_deleted) SELECT coalesce(k0."Cost Center", throwIf(isNull(k0."Cost Center"), 'cells name a member Cost Center does not have')), coalesce(k1."Account", throwIf(isNull(k1."Account"), 'cells name a member Account does not have')), coalesce(k2."Versions", throwIf(isNull(k2."Versions"), 'cells name a member Versions does not have')), coalesce(k3."Years", throwIf(isNull(k3."Years"), 'cells name a member Years does not have')), coalesce(k4."Months", throwIf(isNull(k4."Months"), 'cells name a member Months does not have')), sum(toFloat64(c.value)), toUnixTimestamp64Micro(now64(6)), 0
FROM file('cells/OPEX IN.csv', 'CSVWithNames', '"Cost Center" String, "Account" String, "Versions" String, "Years" String, "Months" String, "value" String') c LEFT JOIN "dim Cost Center" k0 ON k0.name = c."Cost Center" LEFT JOIN "dim Account" k1 ON k1.name = c."Account" LEFT JOIN "dim Versions" k2 ON k2.name = c."Versions" LEFT JOIN "dim Years" k3 ON k3.name = c."Years" LEFT JOIN "dim Months" k4 ON k4.name = c."Months"
